import sys
import json
import numpy as np
import pandas as pd

def to_float(x):
    return float(x) if pd.notna(x) else None

def main():
    path = sys.argv[1]
    df = pd.read_csv(path)

    facts = []

    # ---------- TOTALS ----------
    total_rev_tw = df['Revenue_TW'].sum(skipna=True)
    total_rev_lw = df['Revenue_LW'].sum(skipna=True)
    total_rev_ly = df['Revenue_LY'].sum(skipna=True) if df['Revenue_LY'].notna().any() else np.nan
    total_units_tw = df['Units_TW'].sum(skipna=True)
    total_units_lw = df['Units_LW'].sum(skipna=True)
    total_orders_tw = df['Orders_TW'].sum(skipna=True)
    total_orders_lw = df['Orders_LW'].sum(skipna=True)

    facts.append({
        "entity": "TOTAL", "metric": "revenue", "period": "TW",
        "value": round(float(total_rev_tw), 2),
        "formula": "sum(Revenue_TW)"
    })
    facts.append({
        "entity": "TOTAL", "metric": "revenue", "period": "LW",
        "value": round(float(total_rev_lw), 2),
        "formula": "sum(Revenue_LW)"
    })
    if pd.notna(total_rev_ly):
        facts.append({
            "entity": "TOTAL", "metric": "revenue", "period": "LY",
            "value": round(float(total_rev_ly), 2),
            "formula": "sum(Revenue_LY)"
        })

    if total_rev_lw != 0 and pd.notna(total_rev_lw):
        total_wow = (total_rev_tw - total_rev_lw) / total_rev_lw * 100
        facts.append({
            "entity": "TOTAL", "metric": "revenue", "period": "WoW",
            "value": round(float(total_wow), 1),
            "formula": "(sum(Revenue_TW) - sum(Revenue_LW)) / sum(Revenue_LW) * 100"
        })

    if pd.notna(total_rev_ly) and total_rev_ly != 0:
        total_yoy = (total_rev_tw - total_rev_ly) / total_rev_ly * 100
        facts.append({
            "entity": "TOTAL", "metric": "revenue", "period": "YoY",
            "value": round(float(total_yoy), 1),
            "formula": "(sum(Revenue_TW) - sum(Revenue_LY)) / sum(Revenue_LY) * 100"
        })

    facts.append({
        "entity": "TOTAL", "metric": "units", "period": "TW",
        "value": round(float(total_units_tw), 2),
        "formula": "sum(Units_TW)"
    })
    facts.append({
        "entity": "TOTAL", "metric": "units", "period": "LW",
        "value": round(float(total_units_lw), 2),
        "formula": "sum(Units_LW)"
    })
    facts.append({
        "entity": "TOTAL", "metric": "orders", "period": "TW",
        "value": round(float(total_orders_tw), 2),
        "formula": "sum(Orders_TW)"
    })
    facts.append({
        "entity": "TOTAL", "metric": "orders", "period": "LW",
        "value": round(float(total_orders_lw), 2),
        "formula": "sum(Orders_LW)"
    })

    # ---------- TOP ENTITIES BY REVENUE_TW ----------
    top_rev = df.dropna(subset=['Revenue_TW']).sort_values('Revenue_TW', ascending=False).head(5)
    for _, row in top_rev.iterrows():
        facts.append({
            "entity": row['Entity'], "metric": "revenue", "period": "TW",
            "value": round(float(row['Revenue_TW']), 2),
            "formula": "Revenue_TW"
        })
        if pd.notna(row.get('Share_Pct')):
            facts.append({
                "entity": row['Entity'], "metric": "share", "period": "TW",
                "value": round(float(row['Share_Pct']), 1),
                "formula": "Share_Pct"
            })
        if pd.notna(row.get('Rank')):
            facts.append({
                "entity": row['Entity'], "metric": "rank", "period": "TW",
                "value": float(row['Rank']),
                "formula": "Rank"
            })

    # ---------- BIGGEST WoW MOVERS ----------
    wow_df = df.dropna(subset=['WoW_Pct']).sort_values('WoW_Pct', ascending=False)
    if not wow_df.empty:
        top_gainer = wow_df.iloc[0]
        facts.append({
            "entity": top_gainer['Entity'], "metric": "revenue", "period": "WoW",
            "value": round(float(top_gainer['WoW_Pct']), 1),
            "formula": "(Revenue_TW - Revenue_LW) / Revenue_LW * 100"
        })
        top_loser = wow_df.iloc[-1]
        if top_loser['Entity'] != top_gainer['Entity']:
            facts.append({
                "entity": top_loser['Entity'], "metric": "revenue", "period": "WoW",
                "value": round(float(top_loser['WoW_Pct']), 1),
                "formula": "(Revenue_TW - Revenue_LW) / Revenue_LW * 100"
            })

    # ---------- BIGGEST YoY MOVERS ----------
    yoy_df = df.dropna(subset=['YoY_Pct']).sort_values('YoY_Pct', ascending=False)
    if not yoy_df.empty:
        top_gainer_y = yoy_df.iloc[0]
        facts.append({
            "entity": top_gainer_y['Entity'], "metric": "revenue", "period": "YoY",
            "value": round(float(top_gainer_y['YoY_Pct']), 1),
            "formula": "(Revenue_TW - Revenue_LY) / Revenue_LY * 100"
        })
        top_loser_y = yoy_df.iloc[-1]
        if top_loser_y['Entity'] != top_gainer_y['Entity']:
            facts.append({
                "entity": top_loser_y['Entity'], "metric": "revenue", "period": "YoY",
                "value": round(float(top_loser_y['YoY_Pct']), 1),
                "formula": "(Revenue_TW - Revenue_LY) / Revenue_LY * 100"
            })

    # ---------- UNITS / ORDERS TOP MOVERS ----------
    df_units = df.dropna(subset=['Units_TW', 'Units_LW']).copy()
    if not df_units.empty:
        df_units['Units_WoW_Pct'] = np.where(
            df_units['Units_LW'] != 0,
            (df_units['Units_TW'] - df_units['Units_LW']) / df_units['Units_LW'] * 100,
            np.nan
        )
        df_units_valid = df_units.dropna(subset=['Units_WoW_Pct']).sort_values('Units_WoW_Pct', ascending=False)
        if not df_units_valid.empty:
            top_unit = df_units_valid.iloc[0]
            facts.append({
                "entity": top_unit['Entity'], "metric": "units", "period": "WoW",
                "value": round(float(top_unit['Units_WoW_Pct']), 1),
                "formula": "(Units_TW - Units_LW) / Units_LW * 100"
            })

    df_orders = df.dropna(subset=['Orders_TW', 'Orders_LW']).copy()
    if not df_orders.empty:
        df_orders['Orders_WoW_Pct'] = np.where(
            df_orders['Orders_LW'] != 0,
            (df_orders['Orders_TW'] - df_orders['Orders_LW']) / df_orders['Orders_LW'] * 100,
            np.nan
        )
        df_orders_valid = df_orders.dropna(subset=['Orders_WoW_Pct']).sort_values('Orders_WoW_Pct', ascending=False)
        if not df_orders_valid.empty:
            top_order = df_orders_valid.iloc[0]
            facts.append({
                "entity": top_order['Entity'], "metric": "orders", "period": "WoW",
                "value": round(float(top_order['Orders_WoW_Pct']), 1),
                "formula": "(Orders_TW - Orders_LW) / Orders_LW * 100"
            })

    # Trim to 25 facts max
    facts = facts[:25]

    print(json.dumps(facts))

if __name__ == "__main__":
    main()
